    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def is_pair(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float))

    def pos(v, default=(0, 0)):
        if is_pair(v):
            return v[0], v[1]
        return default

    def get_pairs(v):
        if not isinstance(v, (list, tuple)):
            return []
        out = []
        for it in v:
            if is_pair(it):
                out.append((it[0], it[1]))
        return out

    def move_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def move_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign_pref(a, b):
        if a < b:
            return 1
        if a > b:
            return -1
        return 0

    def nearest(src, items):
        best = None
        best_d = None
        for p in items:
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    def farthest(src, items):
        best = None
        best_d = None
        for p in items:
            d = manhattan(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
